import * as React from 'react';
import { PanelPortalProps } from './PanelPortal';
export type { PanelPosition, PanelSize } from './PanelPortal';
import { CommonProps } from '../utility/commonProps';
export interface PanelProps extends PanelPortalProps, CommonProps {
    /**
     * If the panel is open.
     *
     * @default false
     */
    isOpen?: boolean;
    /**
     * whether to open the panel as modal with background scrim.
     *
     * @default true
     */
    openAsModal?: boolean;
}
/**
 * Panels provide supplemental information or form inputs that relate to the primary canvas.
 *
 * - {@link https://legacy.livingdesign.walmart.com/components/panel/ Guidelines}
 * - {@link https://legacy.livingdesign.walmart.com/components/panel/react/ React documentation}
 *
 * ### Content
 *
 * #### Children
 *
 * The Panel accepts valid React content through the `children` prop:
 *
 * ```tsx
 * <Panel
 *   onClose={() => setIsOpen(false)}
 *   title="Title"
 * >
 *   Content
 * </Panel>
 * ```
 *
 * #### Title
 *
 * The Panel requires a title which can be provided through the `title` prop:
 *
 * ```tsx
 * <Panel
 *   onClose={() => setIsOpen(false)}
 *   title="Title"
 * >
 *   Panel
 * </Panel>
 * ```
 *
 * #### Actions
 *
 * The Panel accepts a group of one or more button-like components through the optional `actions` prop:
 *
 * ```tsx
 * <Panel
 *   actions={
 *     <ButtonGroup>
 *       <Button>Action1</Button>
 *       <Button>Action2</Button>
 *     </ButtonGroup>
 *   }
 *   onClose={() => setIsOpen(false)}
 *   title="Title"
 * >
 *   Content
 * </Panel>
 * ```
 *
 * ### Features
 *
 * #### Size
 *
 * The Panel comes in three sizes:
 * - `small` (default)
 * - `medium`
 * - `large`
 *
 * Set the size with the `size` prop:
 *
 * ```tsx
 * <Panel
 *   onClose={() => setIsOpen(false)}
 *   size="small"
 *   title="Title"
 * >
 *   Small
 * </Panel>
 *
 * <Panel
 *   onClose={() => setIsOpen(false)}
 *   size="medium"
 *   title="Title"
 * >
 *   Medium
 * </Panel>
 *
 * <Panel
 *   onClose={() => setIsOpen(false)}
 *   size="large"
 *   title="Title"
 * >
 *   Large
 * </Panel>
 * ```
 *
 * ### Opening and closing
 *
 * The Panel is set to open or close based on the `isOpen` prop. Provide a callback handler that manages the `isOpen` state through the `onClose` prop:
 *
 * ```tsx
 * export default () => {
 *   const [isOpen, setIsOpen] = React.useState(false);
 *
 *   return (
 *     <>
 *       <Button onClick={() => setIsOpen(true)}>
 *         Open panel
 *       </Button>
 *
 *       <Panel
 *         isOpen={isOpen}
 *         onClose={() => setIsOpen(false)}
 *         title="Title"
 *       >
 *         Content
 *       </Panel>
 *     </>
 *   );
 * };
 * ```
 *
 * ### Layout
 *
 * #### Position
 *
 * The Panel has two different positions:
 *
 * - `left` (default)
 * - `right`
 *
 * Set the position through the `position` prop:
 *
 * ```tsx
 * <Panel
 *   onClose={() => setIsOpen(false)}
 *   position="left"
 *   title="Title"
 * >
 *   Left
 * </Panel>
 *
 * <Panel
 *   onClose={() => setIsOpen(false)}
 *   position="right"
 *   title="Title"
 * >
 *   Right
 * </Panel>
 * ```
 */
export declare const Panel: React.FunctionComponent<PanelProps>;
